output_text:
[
  {
    "id": "items_only_with_cart",
    "text": "A shopper may not pick up an item unless they are currently holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "must_take_entry_cart",
    "text": "At the start of the shopping trip, the shopper is obliged to take the available entrance cart before continuing.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_available": "cartAt(1,5)"
      },
      "events": {
        "cart_acquired": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "entrance_cart_available"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cart_acquired"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Merchandise should not be carried by hand; shoppers should keep items in a cart instead.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull"
      },
      "events": {
        "become_hand_loaded": {
          "pre": "PICKUP_ITEM",
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "become_hand_loaded"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item_pickup",
    "text": "After picking up any shopping item, the shopper is obliged to return the cart to the north-west cart return bay before leaving.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "item_collected": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cart_returned": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "hasCart",
              "return_bay"
            ]
          },
          "post": "cart_at_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "item_collected",
      "discharge": "cart_returned"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A cart may only be put down at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "not_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "cart_left_outside_return_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_left_outside_return_bay"
    }
  },
  {
    "id": "exit_unencumbered",
    "text": "A shopper must not exit the supermarket while still pushing a cart or carrying an item by hand.",
    "abstraction": {
      "state_properties": {
        "encumbered": {
          "or": [
            "hasCart",
            "handFull"
          ]
        }
      },
      "events": {
        "encumbered_exit": {
          "pre": {
            "and": [
              "EXIT",
              "encumbered"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "encumbered_exit"
    }
  },
  {
    "id": "after_return_walk_south",
    "text": "After returning the cart at the north-west return bay, the shopper is obliged to leave that bay by walking south toward the pedestrian exit route.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_at_return_bay": "cartAt(0,1)"
      },
      "events": {
        "cart_returned": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "hasCart",
              "return_bay"
            ]
          },
          "post": "cart_at_return_bay"
        },
        "walk_south_from_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "cart_at_return_bay",
              "S"
            ]
          },
          "post": "at(0,2)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_returned",
      "discharge": "walk_south_from_return_bay"
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Carts should not be pushed along the bottom exit corridor or through the exit.",
    "abstraction": {
      "state_properties": {
        "bottom_exit_corridor": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "cart_moved_in_exit_corridor": {
          "pre": {
            "and": [
              "pushing_cart",
              "bottom_exit_corridor",
              {
                "or": [
                  "E",
                  "W",
                  "EXIT"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_moved_in_exit_corridor"
    }
  }
]
